create or replace function public.create_trade_chain(target_circle_id uuid,chain_title text,chain_description text,execution_value text,links jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare new_id uuid;item jsonb;participant uuid;begin if execution_value not in('simultaneous','sequential','conditional')then raise exception 'invalid execution mode';end if;if not exists(select 1 from public.circle_members where circle_id=target_circle_id and profile_id=auth.uid()and status='active')then raise exception 'active circle membership required';end if;if not exists(select 1 from jsonb_array_elements(links) item where(item->>'from_profile_id')::uuid=auth.uid())then raise exception 'the proposer must participate in the chain';end if;for participant in select distinct(value->>'from_profile_id')::uuid from jsonb_array_elements(links)loop if not exists(select 1 from public.circle_members where circle_id=target_circle_id and profile_id=participant and status='active')then raise exception 'every participant must be active in the circle';end if;end loop;insert into public.trade_chains(proposed_by,circle_id,title,description,execution_mode,status)values(auth.uid(),target_circle_id,trim(chain_title),coalesce(chain_description,''),execution_value,'proposed')returning id into new_id;for item in select value from jsonb_array_elements(links)loop insert into public.trade_chain_links(chain_id,from_profile_id,to_profile_id,value_description,position,due_at,conditions)values(new_id,(item->>'from_profile_id')::uuid,(item->>'to_profile_id')::uuid,trim(item->>'value_description'),coalesce((item->>'position')::int,0),nullif(item->>'due_at','')::timestamptz,coalesce(item->>'conditions',''));end loop;perform public.validate_trade_chain(new_id);insert into public.trade_chain_history(chain_id,actor_id,event,note,snapshot)values(new_id,auth.uid(),'proposed','Chain proposed',jsonb_build_object('version',1,'links',links));for participant in select distinct from_profile_id from public.trade_chain_links where chain_id=new_id loop if participant<>auth.uid()then perform public.notify_user(participant,'network','New circle trade chain',trim(chain_title)||' needs your review.');end if;end loop;return new_id;end$$;
